import itertools

def jac_rank(n,k,seed=0):
    rng=np.random.default_rng(seed)
    # random full-rank X0, then Y0 solving X0^T Y0 = I
    X0=rng.standard_normal((n,k))
    while np.linalg.matrix_rank(X0)<k:
        X0=rng.standard_normal((n,k))
    Y0=X0@np.linalg.inv(X0.T@X0)          # X0^T Y0 = I
    assert np.allclose(X0.T@Y0,np.eye(k))
    # rows: (a,b) entry of X^T dY + dX^T Y ; cols: dX entries then dY entries
    rows=[]
    for a in range(k):
        for b in range(k):
            r=np.zeros(2*n*k)
            for i in range(n):
                r[i*k+a]+= Y0[i,b]        # (dX^T Y)_{ab} = sum_i dX_{ia} Y_{ib}
                r[n*k+i*k+b]+= X0[i,a]    # (X^T dY)_{ab} = sum_i X_{ia} dY_{ib}
            rows.append(r)
    J=np.array(rows)
    rank=np.linalg.matrix_rank(J,tol=1e-8)
    return J.shape, rank, 2*n*k-rank

for (n,k) in [(3,1),(3,2),(4,2),(5,3),(2,2),(4,4),(6,3),(7,5)]:
    shape,rank,dim=jac_rank(n,k)
    print(f"n={n} k={k}: Jacobian {shape}, rank={rank} (expect k^2={k*k}), nullity={dim} (expect 2nk-k^2={2*n*k-k*k})")

# parametrization count check
for (n,k) in [(3,1),(3,2),(4,2),(5,3),(2,2),(4,4),(6,3),(7,5)]:
    print(f"n={n} k={k}: nk + k(n-k) = {n*k + k*(n-k)}   vs 2nk-k^2 = {2*n*k-k*k}")
