import numpy as np

# Numeric sanity check of the mechanism: E = [0,1] U [2,3], density points e=0.5, f=2.5
def ratio_outside(center, E, d):
    lo, hi = center-d, center+d
    # measure of E inside [lo,hi]
    def len_inter(a,b,c,dd):
        L = max(0.0, min(b,dd)-max(a,c))
        return L
    mE = len_inter(lo,hi,0,1) + len_inter(lo,hi,2,3)
    return (2*d - mE)/(2*d)

for eps in [0.1, 0.01, 0.001]:
    for center in [0.5, 2.5]:
        d = 1.0
        while d > 1e-12:
            r = ratio_outside(center, None, d)
            if r < eps:
                break
            d /= 2
        print(f"eps={eps} center={center} smallest-searched delta={d:.3e} ratio={r:.3e}")

# Counterexample check: a NON-density point (e=0 for E=(0,1)) fails for eps<1/2
def ratio_half(d):
    mE = max(0.0, min(1, d) - max(0, -d))
    return (2*d - mE)/(2*d)
print("e=0 for E=(0,1): ratio =", [round(ratio_half(d),4) for d in [1,0.1,0.01,1e-4]])
