import itertools

def make_group(table, n):
    # table[i][j] = product index
    return table, n

def group_Zm(m):
    n=m
    tab=[[ (i+j)%m for j in range(n)] for i in range(n)]
    return tab,n

def group_Z2Z2():
    els=[(0,0),(1,0),(0,1),(1,1)]
    idx={e:i for i,e in enumerate(els)}
    n=len(els)
    tab=[[idx[(a[0]+b[0])%2,(a[1]+b[1])%2] for b in els] for a in els]
    return tab,n

def group_S3():
    # permutations of 3 letters as tuples
    import itertools as it
    els=list(it.permutations(range(3)))
    idx={e:i for i,e in enumerate(els)}
    n=len(els)
    def mul(p,q): return tuple(p[q[i]] for i in range(3))
    tab=[[idx[mul(a,b)] for b in els] for a in els]
    return tab,n

def inv(tab,n):
    e=[tab[i][j] for i in range(n) for j in range(n)]
    # identity: element e with tab[e][j]==j and tab[j][e]==j all j
    for e0 in range(n):
        if all(tab[e0][j]==j and tab[j][e0]==j for j in range(n)):
            idn=e0; break
    invs=[0]*n
    for i in range(n):
        for j in range(n):
            if tab[i][j]==idn and tab[j][i]==idn:
                invs[i]=j
    return idn, invs

def subgroup_gen(gens, tab, n):
    idn,invs=inv(tab,n)
    S={idn}; frontier=[idn]
    gens=list(set(gens))
    while frontier:
        x=frontier.pop()
        for g in gens:
            for y in (tab[x][g], tab[g][x]):
                if y not in S:
                    S.add(y); frontier.append(y)
    return S

def endos(tab,n):
    """all homomorphisms sigma:G->G as tuples sigma[0..n-1]"""
    res=[]
    for f in itertools.product(range(n), repeat=n):
        ok=True
        for a in range(n):
            for b in range(n):
                if f[tab[a][b]] != tab[f[a]][f[b]]:
                    ok=False; break
            if not ok: break
        if ok: res.append(f)
    return res

def centralizer_of_set(S, tab, n):
    idn,invs=inv(tab,n)
    out=[]
    for x in range(n):
        if all(tab[x][s]==tab[s][x] for s in S):
            out.append(x)
    return out

def analyze(name, tab, n):
    idn,invs=inv(tab,n)
    E=endos(tab,n)
    surj_not_inj=0; surj=0; total_phi=0
    surj_endo_G=0; inj_endo_G=0
    for sigma in E:
        im=set(sigma)
        imG = subgroup_gen(list(im), tab, n)   # subgroup generated by im(sigma)
        # sigma surjective as map G->G?
        if im==set(range(n)):
            surj_endo_G+=1
            if len(set(sigma))==n: inj_endo_G+=1
        cen = centralizer_of_set(im, tab, n)
        for k in range(-3,4):
            for x in cen:
                # phi(n,g) = (n*k, x^n sigma(g)) ; valid homomorphism since x centralizes im sigma
                total_phi+=1
                # image: Z-part = k*Z ; G-part = <x, im sigma>
                H = subgroup_gen([x]+list(im), tab, n)
                is_surj = (abs(k)==1) and (H==set(range(n)))
                # kernel: (n,g) with n*k=0 and x^n sigma(g)=id
                if k!=0:
                    ker = {(0,g) for g in range(n) if sigma[g]==idn}
                else:
                    # n*k=0 for all n; need x^n sigma(g)=id for some/all n -> big kernel
                    ker = {(0,g) for g in range(n) if sigma[g]==idn}
                    ker = ker | {(1,0)}  # nontrivial already if id in im... just mark nontrivial
                is_inj = (k!=0) and (ker=={(0,idn)})
                if is_surj:
                    surj+=1
                    if not is_inj:
                        surj_not_inj+=1
    print(f"{name}: |G|={n}, |End(G)|={len(E)}, surjective phi on Z x G: {surj}, surjective-but-not-injective: {surj_not_inj}, "
          f"surj endos of G={surj_endo_G}, inj endos of G={inj_endo_G}")
    return surj_not_inj

bad=0
for nm,tab,n in [("Z/2",*group_Zm(2)),("Z/3",*group_Zm(3)),("Z/4",*group_Zm(4)),
                 ("Z/6",*group_Zm(6)),("Z/2 x Z/2",*group_Z2Z2()),("S3",*group_S3())]:
    bad+=analyze(nm,tab,n)
print("TOTAL surjective non-injective endomorphisms of Z x G found:", bad)
"}

